## Building a Countdown Timer

### Timer State

```xiom
type Timer {
  total_seconds: Int;
  remaining: Int;
  running: Bool;
}

fn create_timer(hours: Int, minutes: Int, seconds: Int) -> Timer {
  let total = hours * 3600 + minutes * 60 + seconds;
  Timer{ total_seconds: total, remaining: total, running: true }
}
```

### Formatting Time

```xiom
fn format_time(total_seconds: Int) -> Str {
  let h = total_seconds / 3600;
  let m = (total_seconds % 3600) / 60;
  let s = total_seconds % 60;

  let mut result = pad_zero(h);
  result = string.str_concat(result, ":");
  result = string.str_concat(result, pad_zero(m));
  result = string.str_concat(result, ":");
  result = string.str_concat(result, pad_zero(s));
  result
}

fn pad_zero(n: Int) -> Str {
  if n < 10 {
    let s = "0";
    return string.str_concat(s, int_to_str(n));
  };
  int_to_str(n)
}
```

### Ticking the Timer

```xiom
fn tick(timer: &mut Timer) -> Bool {
  if !timer.running { return false; };
  if timer.remaining <= 0 {
    timer.running = false;
    return false;
  };
  timer.remaining -= 1;
  timer.remaining > 0
}
```

### Running a Countdown

```xiom
fn run_timer(timer: &mut Timer, ticks: Int) {
  let mut i = 0;
  while i < ticks && timer.running {
    io.println(format_time(timer.remaining));
    tick(timer);
    i += 1;
  };

  if timer.remaining == 0 {
    io.println("00:00:00");
    io.println("Time's up!");
  };
}
```

### Common Timer Durations

- Pomodoro: 25 minutes (0:25:00)
- Break: 5 minutes (0:05:00)
- New Year: 10 seconds (0:00:10)
- Exam: 180 minutes (3:00:00)

