use xiom.io;

use xiom.string;
type Countdown = {
  seconds: Int;
}

fn format_timer(seconds: Int) -> Str {
  let m = seconds / 60;
  let s = seconds % 60;
  var result = "";
  if m < 10 { result = string.str_concat(result, "0"); };
  result = string.str_concat(result, to_string(m));
  result = string.str_concat(result, ":");
  if s < 10 { result = string.str_concat(result, "0"); };
  result = string.str_concat(result, to_string(s));
  result
}

fn tick(timer: &mut Countdown) -> Bool {
  if timer.seconds <= 0 { return false; };
  timer.seconds -= 1;
  timer.seconds > 0
}

fn main() -> Int {
  var timer = Countdown{ seconds: 10 };
  var i = 0;
  while i < 12 {
    io.println(format_timer(timer.seconds));
    tick(&mut timer);
    i += 1;
  };
  return 0;
}
